                    for rr in range(r + 1, h):
                        out[rr][c] = color
                elif hi == w - 1:
                    for rr in range(r):
                        out[rr][c] = color

    # Vertical marker segments extend toward the first horizontal bar whose
    # span contains that column, stopping at the bar.
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c]]
        if len(ys) >= 2 and len({grid[r][c] for r in ys}) == 1:
            color = grid[ys[0]][c]
            targets = [r for r, lo, hi in bars if lo <= c <= hi and r > ys[-1]]
            if targets:
                target = min(targets)
                for rr in range(ys[-1] + 1, target):
                    out[rr][c] = color
    return out
